  useEffect(()=>{if(s.modal&&s.modal.startsWith("edit-")&&s.md){const item={...s.md};if(Array.isArray(item.vehicles))item.vehicles=item.vehicles.join(", ");if(Array.isArray(item.tags))item.tags=item.tags.join(", ");if(Array.isArray(item.specialties))item.specialties=item.specialties.join(", ");if(Array.isArray(item.certs))item.certs=item.certs.join(", ");Object.keys(item).forEach(k=>{if(k!=="id"&&typeof item[k]==="number")item[k]=String(item[k]);});sf(item);}else{const m=s.md||{};sf({...(m.cat?{cat:m.cat}:{}),...(m.status?{status:m.status}:{}),...(m.custId?{custId:String(m.custId)}:{}),...(m.engineId?{engineId:m.engineId,engineName:m.engineName}:{})});}setLines(s.md&&Array.isArray(s.md.prefillItems)&&s.md.prefillItems.length?s.md.prefillItems:[{d:"",q:1,r:0}]);},[s.modal]);
  if(!s.modal)return null;
  const W=ch=>(<div className="rc-ov" onClick={()=>d({type:"CLOSE"})}><div className="rc-mod" onClick={e=>e.stopPropagation()}>{ch}</div></div>);
  const DATEKEYS=["date","dueDate","shipDate","estDelivery","expiryDate","startDate","orderDate","eta","followUp"];
  const F=(k,l,t)=>(<div className="rc-fg"><label className="rc-fl">{l}</label><input className="rc-fi" value={f[k]||""} onChange={e=>set(k,e.target.value)} placeholder={l} type={t||(DATEKEYS.includes(k)?"date":"text")}/></div>);
  const CS=()=>(<div className="rc-fg"><label className="rc-fl">Customer</label><select className="rc-fi" value={f.custId||""} onChange={e=>set("custId",e.target.value)} style={{appearance:"none"}}><option value="">Select...</option>{(s.customers||[]).map(c=>(<option key={c.id} value={c.id}>{c.name}</option>))}</select></div>);
  const ES=(auto)=>(<div className="rc-fg"><label className="rc-fl">Engine (optional)</label><select className="rc-fi" value={f.engineId||""} onChange={e=>{const id=+e.target.value;const eng=(s.inventory||[]).find(x=>x.id===id);set("engineId",e.target.value);if(eng&&auto)auto(eng);}} style={{appearance:"none"}}><option value="">Not linked</option>{(s.inventory||[]).filter(isEngine).map(eng=>(<option key={eng.id} value={eng.id}>{eng.name} {eng.serial?`· ESN ${eng.serial}`:""}</option>))}</select></div>);
  const TS=()=>(<div className="rc-fg"><label className="rc-fl">Technician</label><select className="rc-fi" value={f.tech||""} onChange={e=>set("tech",e.target.value)} style={{appearance:"none"}}><option value="">Unassigned</option>{(s.employees||[]).filter(e=>e.status==="active").map(e=>(<option key={e.id} value={e.nick||e.name}>{e.name}</option>))}</select></div>);
  const PH=()=>(<div className="rc-fg"><label className="rc-fl">Photo</label>{f.photo?(<div style={{position:"relative",marginBottom:6}}><img src={f.photo} alt="" style={{width:"100%",maxHeight:160,objectFit:"cover",borderRadius:4,border:"1px solid #2a2a2a"}}/><button className="rc-bs rc-bsr" onClick={()=>{deletePhoto(f.photo);set("photo","");if(s.modal==="edit-part"&&s.md&&s.md.id)d({type:"UPDATE",list:"inventory",id:s.md.id,d:{photo:""}});}} style={{position:"absolute",top:6,right:6,fontSize:9}}>Remove</button></div>):null}<div style={{display:"flex",gap:6,alignItems:"center"}}><label className="rc-bs" style={{cursor:uploading?"default":"pointer",textAlign:"center",opacity:uploading?.6:1}}>{uploading?"⏳ Uploading…":"📷 Upload"}<input type="file" accept="image/*" disabled={uploading} onChange={e=>{const file=e.target.files[0];if(!file)return;setUploading(true);uploadPhoto(file).then(u=>{const old=f.photo;if(old&&old!==u)deletePhoto(old);set("photo",u);if(s.modal==="edit-part"&&s.md&&s.md.id){d({type:"UPDATE",list:"inventory",id:s.md.id,d:{photo:u}});d({type:"TOAST",d:{msg:"📷 Photo saved",t:Date.now()}});}}).catch(err=>{console.error("photo upload failed:",err&&err.message?err.message:err);d({type:"TOAST",d:{msg:"⚠ Photo upload failed — try again",t:Date.now()}});}).finally(()=>setUploading(false));}} style={{display:"none"}}/></label><input className="rc-fi" placeholder="...or paste image URL" value={(f.photo||"").startsWith("data:")?"":(f.photo||"")} onChange={e=>set("photo",e.target.value)} style={{flex:1}}/></div></div>);
  const C=<button className="rc-bs" onClick={()=>d({type:"CLOSE"})}>Close</button>;
  const X=<button className="rc-bs" onClick={()=>d({type:"CLOSE"})}>Cancel</button>;
  const FM=(t,flds,onSave)=>W(<div><div className="rc-mt">{t}</div>{flds.map(([k,l,tp])=>F(k,l,tp))}<div className="rc-fa">{X}<button className="rc-ba" onClick={onSave}>Save</button></div></div>);
  const EFM=(t,list,flds,tr)=>W(<div><div className="rc-mt">{t}</div>{flds.map(([k,l,tp])=>F(k,l,tp))}<div className="rc-fa">{X}<button className="rc-ba" onClick={()=>{d({type:"UPDATE",list,id:s.md.id,d:tr?tr(f):f});d({type:"CLOSE"});}}>Save Changes</button></div></div>);
  const LI=()=>(<>{lines.map((li,i)=>(<div key={i} style={{display:"grid",gridTemplateColumns:"1fr 50px 70px 28px",gap:6,marginBottom:6}}><input className="rc-fi" placeholder="Description" value={li.d} onChange={e=>{const nl=[...lines];nl[i]={...nl[i],d:e.target.value};setLines(nl);}}/><input className="rc-fi" placeholder="Qty" type="number" value={li.q} onChange={e=>{const nl=[...lines];nl[i]={...nl[i],q:+e.target.value||0};setLines(nl);}}/><input className="rc-fi" placeholder="Rate" type="number" value={li.r} onChange={e=>{const nl=[...lines];nl[i]={...nl[i],r:+e.target.value||0};setLines(nl);}}/><button className="rc-bs" style={{padding:"8px 0"}} onClick={()=>setLines(lines.filter((_,j)=>j!==i))}>×</button></div>))}<button className="rc-bs" onClick={()=>setLines([...lines,{d:"",q:1,r:0}])} style={{marginBottom:10}}>+ Line</button></>);
